   {
    "name": "Headline figures",
    "what": "The KPI tiles. Read these first — they summarise the whole view."
   },
   {
    "name": "Charts",
    "what": "SVG charts drawn locally, with a table fallback if a chart cannot render."
   },
   {
    "name": "Methodology note",
    "what": "The published formula behind every number. Nothing here is a black box, so you can defend any figure to a parent."
   },
   {
    "name": "Print / export",
    "what": "Produces a clean, chrome-free layout suitable for a parent conference."
   }
